import json, re

with open('/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0514-4-projects-distrib-canary-collapse/50cbae2b-b97f-497a-bfed-63d281a16b42/tool-results/mcp-agent-ml-research-read_registry-1779209194577.txt', 'r') as f:
    raw = json.load(f)

registry = json.loads(raw['result'])
experiments = registry['data']['experiments']

# Search ALL experiments for PermG numeric values
def find_perm_values(d, path=''):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            new_path = f'{path}.{k}'
            k_lower = k.lower()
            if re.search(r'perm.*g|granger', k_lower):
                results.append((new_path, v))
            if k_lower in ('lead_lag', 'leadlag', 'lead-lag'):
                results.append((new_path, v))
            if k_lower == 'notes' and isinstance(v, str) and re.search(r'(?i)perm', v):
                results.append((new_path, v))
            results.extend(find_perm_values(v, new_path))
    elif isinstance(d, list):
        for i, v in enumerate(d):
            results.extend(find_perm_values(v, f'{path}[{i}]'))
    return results

# Check all experiments
for name, exp in experiments.items():
    found = find_perm_values(exp, name)
    if found:
        for path, val in found:
            print(f'{path}: {val}')
